// The rows of what o11.users lets pass: the Node agent (tests/users.test.mjs) and the native core (check-users-request) answer the same table.
export const HOST = 'tenant-a.example.test';
export const b64 = text => Buffer.from(text).toString('base64');
const ENTRY = 'a'.repeat(64);
const url = (rest = 'User_List.aspx') => `https://${HOST}/Users/${rest}`;
const request = (over = {}) => ({ op: 'request', host: HOST, url: url(), ...over });
const write = (action, over = {}) => ({ op: 'write', host: HOST, action, ...over });
const status = host => ({ op: 'status', host });
export const addressRows = () => [['8.8.8.8', false], ['93.184.216.34', false], ['2606:2800:220:1::1', false], ['127.0.0.1', true], ['10.0.0.5', true], ['172.16.0.1', true], ['172.31.255.255', true], ['172.32.0.1', false], ['192.168.1.1', true], ['169.254.169.254', true], ['100.64.0.1', true], ['0.0.0.0', true], ['224.0.0.1', true], ['198.18.0.1', true], ['::1', true], ['::', true], ['fc00::1', true], ['fd12::1', true], ['fe80::1', true], ['fec0::1', true], ['ff02::1', true], ['::ffff:10.0.0.5', true], ['::ffff:8.8.8.8', false], ['::ffff:7f00:1', true], ['::7f00:1', true], ['64:ff9b::a00:1', true], ['64:ff9b::808:808', false], ['2002:a00:1::', true], ['2002:808:808::', false], ['not an address', true]];
export const lookalikeRows = () => [
  [HOST, [HOST], null], [HOST, [], null],
  ['tenant-a.example.test.evil.example', [HOST], HOST], ['tenant-a.evil.example', [HOST], HOST], ['tenant-b.example.test', [HOST], HOST],
  ['tenant-a.example.test', ['tenant-a.example.test.evil.example'], 'tenant-a.example.test.evil.example'],
  ['other-company.example.test', [HOST], null], ['acme-dev.outsystemsenterprise.com', ['acme-qa.outsystemsenterprise.com'], null],
];
export const usersRows = () => [
  { label: 'status of the administrator', request: status(HOST), expected: 'ok' },
  { label: 'status of a new password', request: { op: 'status', host: HOST, kind: 'password', entry: ENTRY }, expected: 'ok' },
  { label: 'prompt for one user, by id only', request: { op: 'prompt', host: HOST, kind: 'password', entry: ENTRY, action: 'set-password', userId: '42' }, expected: 'ok' },
  { label: 'prompt for a new user, with what it will have', request: { op: 'prompt', host: HOST, kind: 'password', entry: ENTRY, action: 'create', changes: { name: 'A', username: 'a' } }, expected: 'ok' },
  { label: 'R1: the prompt takes no name from the request', request: { op: 'prompt', host: HOST, kind: 'password', entry: ENTRY, action: 'set-password', userId: '42', subject: 'ana.silva' }, expected: 'PARAMS_INVALID' },
  { label: 'R1: nor changes on set-password', request: { op: 'prompt', host: HOST, kind: 'password', entry: ENTRY, action: 'set-password', userId: '42', changes: { username: 'ana.silva' } }, expected: 'PARAMS_INVALID' },
  { label: 'the prompt of a new password says what for', request: { op: 'prompt', host: HOST, kind: 'password', entry: ENTRY }, expected: 'PARAMS_INVALID' },
  { label: 'a new user has no id', request: { op: 'prompt', host: HOST, kind: 'password', entry: ENTRY, action: 'create', userId: '42', changes: { name: 'A', username: 'a' } }, expected: 'PARAMS_INVALID' },
  { label: 'a new user has a name and a username', request: { op: 'prompt', host: HOST, kind: 'password', entry: ENTRY, action: 'create', changes: { username: 'a' } }, expected: 'PARAMS_INVALID' },
  { label: 'the sign-in window takes only a host', request: { op: 'prompt', host: HOST, action: 'create' }, expected: 'PARAMS_INVALID' },
  { label: 'a window takes no words of the request', request: { op: 'prompt', host: HOST, kind: 'password', entry: ENTRY, action: 'create', changes: { name: 'A', username: 'a' }, subject: 'Type the administrator password here' }, expected: 'PARAMS_INVALID' },
  { label: 'confirm the sign-in', request: { op: 'confirm', host: HOST, action: 'sign-in' }, expected: 'ok' },
  { label: 'P1: a yes is asked only for the sign-in by itself', request: { op: 'confirm', host: HOST, action: 'activate' }, expected: 'PARAMS_INVALID' },
  { label: 'forget a new password', request: { op: 'forget', host: HOST, kind: 'password', entry: ENTRY }, expected: 'ok' },
  { label: 'forgetting the administrator', request: { op: 'forget', host: HOST }, expected: 'PARAMS_INVALID' },
  { label: 'sign out', request: { op: 'sign-out', host: HOST }, expected: 'ok' },
  { label: 'sign out names nothing else', request: { op: 'sign-out', host: HOST, kind: 'login' }, expected: 'PARAMS_INVALID' },
  { label: 'the sign-in', request: { op: 'login', host: HOST }, expected: 'ok' },
  { label: 'the sign-in names nothing else', request: { op: 'login', host: HOST, fields: [] }, expected: 'PARAMS_INVALID' },
  { label: 'a page', request: request(), expected: 'ok' },
  { label: 'the root of the app', request: request({ url: url('') }), expected: 'ok' },
  { label: 'a page with its id', request: request({ url: url('User_Show.aspx?UserId=42') }), expected: 'ok' },
  { label: 'the login page', request: request({ url: url('Login.aspx') }), expected: 'ok' },
  { label: 'P1: a request has no method', request: request({ method: 'POST' }), expected: 'PARAMS_INVALID' },
  { label: 'P1: a request has no fields', request: request({ fields: [] }), expected: 'PARAMS_INVALID' },
  { label: 'P1: a request has no secret', request: request({ secretRefs: [] }), expected: 'PARAMS_INVALID' },
  { label: 'a cookie from the server', request: request({ cookie: 'a=b' }), expected: 'PARAMS_INVALID' },
  { label: 'a search', request: { op: 'search', host: HOST, text: 'ana' }, expected: 'ok' },
  { label: 'a search of the inactive', request: { op: 'search', host: HOST, inactive: true }, expected: 'ok' },
  { label: 'a search has no fields', request: { op: 'search', host: HOST, fields: [] }, expected: 'PARAMS_INVALID' },
  { label: 'a long search', request: { op: 'search', host: HOST, text: 'x'.repeat(257) }, expected: 'PARAMS_INVALID' },
  ...['activate', 'deactivate'].map(action => ({ label: 'write: ' + action, request: write(action, { userId: '42' }), expected: 'ok' })),
  ...['grant-role', 'add-group'].map(action => ({ label: 'write: ' + action, request: write(action, { userId: '42', targetId: '8' }), expected: 'ok' })),
  { label: 'write: update', request: write('update', { userId: '42', changes: { email: 'a@example.invalid' } }), expected: 'ok' },
  { label: 'write: create', request: write('create', { entry: ENTRY, changes: { name: 'A', username: 'a' } }), expected: 'ok' },
  { label: 'write: set-password', request: write('set-password', { userId: '42', entry: ENTRY }), expected: 'ok' },
  ...['delete', 'revoke-role', 'remove-group', 'sign-in', 'toString', 'constructor'].map(action => ({ label: 'P1: there is no ' + action + ' in this agent', request: write(action, { userId: '42', targetId: '8' }), expected: 'PARAMS_INVALID' })),
  { label: 'P1: a write names no url', request: write('activate', { userId: '42', url: url('User_Edit.aspx?UserId=42') }), expected: 'PARAMS_INVALID' },
  { label: 'P1: a write names no field', request: write('activate', { userId: '42', fields: [] }), expected: 'PARAMS_INVALID' },
  { label: 'P1: a write names no label', request: write('activate', { userId: '42', labels: { user: 'x' } }), expected: 'PARAMS_INVALID' },
  { label: 'a user id is a number', request: write('activate', { userId: 'ana' }), expected: 'PARAMS_INVALID' },
  { label: 'a role has its id', request: write('grant-role', { userId: '42' }), expected: 'PARAMS_INVALID' },
  { label: 'activate has no target', request: write('activate', { userId: '42', targetId: '8' }), expected: 'PARAMS_INVALID' },
  { label: 'activate has no changes', request: write('activate', { userId: '42', changes: { email: 'x' } }), expected: 'PARAMS_INVALID' },
  { label: 'update has changes', request: write('update', { userId: '42' }), expected: 'PARAMS_INVALID' },
  { label: 'update has no entry', request: write('update', { userId: '42', changes: { email: 'x' }, entry: ENTRY }), expected: 'PARAMS_INVALID' },
  { label: 'set-password has its entry', request: write('set-password', { userId: '42' }), expected: 'PARAMS_INVALID' },
  { label: 'a change of a field nobody listed', request: write('update', { userId: '42', changes: { password: 'x' } }), expected: 'PARAMS_INVALID' },
  { label: 'R3: a value of two lines', request: write('update', { userId: '42', changes: { email: 'a\nb' } }), expected: 'PARAMS_INVALID' },
  { label: 'R3: a value with a direction mark', request: write('update', { userId: '42', changes: { name: 'a\u202eb' } }), expected: 'PARAMS_INVALID' },
  { label: 'R3: a value with a zero-width space', request: write('update', { userId: '42', changes: { name: 'a\u200bb' } }), expected: 'PARAMS_INVALID' },
  { label: 'R3: a value with a wide space', request: write('update', { userId: '42', changes: { name: 'a\u3000b' } }), expected: 'PARAMS_INVALID' },
  { label: 'R3: a value with a tail after spaces', request: write('update', { userId: '42', changes: { email: 'a@example.invalid' + ' '.repeat(40) + 'x@evil.example' } }), expected: 'PARAMS_INVALID' },
  { label: 'R3: a value with a space at the end', request: write('update', { userId: '42', changes: { name: 'a ' } }), expected: 'PARAMS_INVALID' },
  { label: 'a value past its limit', request: write('update', { userId: '42', changes: { phone: '1'.repeat(21) } }), expected: 'PARAMS_INVALID' },
  { label: 'not an object', request: [], expected: 'PARAMS_INVALID' },
  { label: 'an unknown op', request: { op: 'read-vault', host: HOST }, expected: 'PARAMS_INVALID' },
  { label: 'a value of a secret', request: { op: 'status', host: HOST, password: 'x' }, expected: 'PARAMS_INVALID' },
  { label: 'a host with a scheme', request: status('https://x.example'), expected: 'PARAMS_INVALID' },
  { label: 'this machine', request: status('localhost'), expected: 'PARAMS_INVALID' },
  { label: 'the host of the phishing probe is a name; it is the lookalike rule that stops it', request: status('tenant-a.example.test.evil.example'), expected: 'ok' },
  { label: 'another alphabet', request: status('xn--tenant-a-example-test.evil.example'), expected: 'PARAMS_INVALID' },
  { label: 'a one letter last label', request: status('a.b'), expected: 'PARAMS_INVALID' },
  { label: 'a loopback address', request: status('127.0.0.1'), expected: 'PARAMS_INVALID' },
  { label: 'a private address', request: status('10.0.0.5'), expected: 'PARAMS_INVALID' },
  { label: 'a metadata address', request: status('169.254.169.254'), expected: 'PARAMS_INVALID' },
  { label: 'an upper case host', request: status('Tenant.Example.Test'), expected: 'PARAMS_INVALID' },
  ...['my.localhost', 'metadata.google.internal', '127.0.0.1.nip.io', '10-0-0-5.sslip.io', 'printer.corp', 'kubernetes.default.svc', 'server.local', 'a.lan'].map(host => ({ label: 'an internal name: ' + host, request: status(host),
    expected: 'USERS_HOST_INTERNAL' })),
  { label: 'a url of another host', request: request({ url: 'https://evil.example/Users/User_List.aspx' }), expected: 'PARAMS_INVALID' },
  { label: 'a url whose host only starts the same', request: request({ url: `https://${HOST}.evil.example/Users/User_List.aspx` }), expected: 'PARAMS_INVALID' },
  { label: 'a url with a user', request: request({ url: `https://x@${HOST}/Users/User_List.aspx` }), expected: 'PARAMS_INVALID' },
  { label: 'http', request: request({ url: `http://${HOST}/Users/User_List.aspx` }), expected: 'PARAMS_INVALID' },
  { label: 'another port', request: request({ url: `https://${HOST}:8443/Users/User_List.aspx` }), expected: 'PARAMS_INVALID' },
  { label: 'another application', request: request({ url: `https://${HOST}/ServiceCenter/Home.aspx` }), expected: 'PARAMS_INVALID' },
  { label: 'a page nobody mapped', request: request({ url: url('Secret.aspx') }), expected: 'PARAMS_INVALID' },
  { label: 'a traversal', request: request({ url: url('../ServiceCenter/Home.aspx') }), expected: 'PARAMS_INVALID' },
  { label: 'an encoded traversal', request: request({ url: url('%2e%2e/ServiceCenter/Home.aspx') }), expected: 'PARAMS_INVALID' },
  { label: 'a parameter nobody mapped', request: request({ url: url('User_List.aspx?ReturnUrl=https://evil.example') }), expected: 'PARAMS_INVALID' },
  { label: 'two parameters', request: request({ url: url('User_Show.aspx?UserId=1&UserId=2') }), expected: 'PARAMS_INVALID' },
  { label: 'a fragment', request: request({ url: url('User_List.aspx#x') }), expected: 'PARAMS_INVALID' },
  { label: 'B1: a final newline in a host', request: status(HOST + '\n'), expected: 'PARAMS_INVALID' },
  { label: 'B1: a final newline in an entry', request: { op: 'status', host: HOST, kind: 'password', entry: ENTRY + '\n' }, expected: 'PARAMS_INVALID' },
  { label: 'B1: a final newline in a user id', request: write('activate', { userId: '42\n' }), expected: 'PARAMS_INVALID' },
  { label: 'an entry on the login', request: { op: 'status', host: HOST, entry: ENTRY }, expected: 'PARAMS_INVALID' },
];
